import com.surprising.aeron.client.SurprisingAeronClient;
import com.surprising.aeron.protocol.*;
import com.surprising.product.api.ProductLine;
import java.time.Duration;
import java.util.List;
import java.util.UUID;

class TransferGate {
    final ProductLine line = ProductLine.requireExternalCode(System.getProperty("surprising.aeron.product-line"));
    final String asset = line.name().startsWith("INVERSE") ? "BTC" : "USDT";
    final long sender = 680001, recipient = 680002;
    final TransferFundsCommand transfer = new TransferFundsCommand(680091, line, line,
            line.accountTypeCode(), line.accountTypeCode(), asset, 37, "round68-transfer", "跨用户", sender, recipient);
    final SurprisingAeronClient client;
    TransferGate(SurprisingAeronClient client) { this.client = client; }
    CoreResponse command(CoreMessageType type, long user, int id, byte[] data) {
        return client.submit(new CoreMessage(CoreMessageHeader.command(type, new UUID(6800, id), line,
                CommandSource.OPERATIONS, 968001, id, user, 1792880000000L, id), data));
    }
    void applied(CoreMessageType type, long user, int id, byte[] data) {
        var result = command(type, user, id, data);
        if (result.commandStatus() != ResponseStatus.APPLIED) throw new AssertionError(type+" "+result.resultCode());
    }
    byte[] query(CoreMessageType type, long user, byte[] data) {
        var result = client.submit(new CoreMessage(CoreMessageHeader.query(type, UUID.randomUUID(), line,
                CommandSource.OPERATIONS, 968001, 0, user, 1792880000000L, 0), data));
        if (result.status() != ResponseStatus.OK) throw new AssertionError(type+" "+result.resultCode());
        return result.data();
    }
    void balances(long source, long target) {
        long sum=0;
        for (long user : new long[]{sender, recipient}) {
            var state=CoreStateQueryCodec.decodeUserState(query(CoreMessageType.USER_STATE_QUERY,user,new byte[0]));
            if (!state.positions().isEmpty() || !state.reservations().isEmpty() || state.balances().size()!=1)
                throw new AssertionError("unexpected account facts "+state);
            var balance=state.balances().getFirst();
            if (!balance.asset().equals(asset) || balance.lockedUnits()!=0
                    || balance.availableUnits()!=(user==sender?source:target)) throw new AssertionError("balance "+balance);
            sum=Math.addExact(sum,balance.availableUnits());
        }
        if (sum!=source+target) throw new AssertionError("funds sum");
    }
    void pending(boolean exists) {
        byte[] frame=query(CoreMessageType.PENDING_TRANSFER_QUERY,0,CorePendingTransferCodec.encodeQuery(256));
        var pending=CorePendingTransferCodec.decode(frame);
        if (exists) {
            if (!pending.equals(List.of(transfer)) || frame.length!=8+TradingCommandCodec.encodeTransferFunds(transfer).length)
                throw new AssertionError("pending command/wire length");
        } else if (!pending.isEmpty() || frame.length!=4) throw new AssertionError("pending was not removed");
    }
    void rejected(CoreMessageType type,long user,int id,byte[] payload) {
        var response=command(type,user,id,payload);
        if (response.commandStatus()!=ResponseStatus.REJECTED || response.resultCode()!=CoreResultCode.IDEMPOTENCY_CONFLICT)
            throw new AssertionError("wrong user accepted "+type+" "+response.resultCode());
    }
    void prepare() {
        applied(CoreMessageType.ADJUST_BALANCE,sender,1,TradingCommandCodec.encodeBalanceAdjustment(new BalanceAdjustmentCommand(asset,1000)));
        applied(CoreMessageType.ADJUST_BALANCE,recipient,2,TradingCommandCodec.encodeBalanceAdjustment(new BalanceAdjustmentCommand(asset,100)));
        applied(CoreMessageType.TRANSFER_OUT,sender,3,TradingCommandCodec.encodeTransferFunds(transfer));
        pending(true); balances(963,100);
        System.out.println("TRANSFER_GATE_PASS product="+line+" phase=pending source=963 target=100 inFlight=37");
    }
    void settle() {
        pending(true); balances(963,100);
        if (command(CoreMessageType.TRANSFER_OUT,sender,3,TradingCommandCodec.encodeTransferFunds(transfer)).status()!=ResponseStatus.DUPLICATE)
            throw new AssertionError("recovered transfer-out debit repeated");
        rejected(CoreMessageType.TRANSFER_OUT,recipient,4,TradingCommandCodec.encodeTransferFunds(transfer));
        rejected(CoreMessageType.TRANSFER_IN,sender,5,TradingCommandCodec.encodeTransferFunds(transfer));
        rejected(CoreMessageType.COMPLETE_TRANSFER,recipient,6,TradingCommandCodec.encodeCompleteTransfer(new CompleteTransferCommand(transfer.transferId())));
        pending(true); balances(963,100);
        applied(CoreMessageType.TRANSFER_IN,recipient,7,TradingCommandCodec.encodeTransferFunds(transfer));
        if (command(CoreMessageType.TRANSFER_IN,recipient,7,TradingCommandCodec.encodeTransferFunds(transfer)).status()!=ResponseStatus.DUPLICATE)
            throw new AssertionError("transfer-in credit repeated");
        applied(CoreMessageType.COMPLETE_TRANSFER,sender,8,TradingCommandCodec.encodeCompleteTransfer(new CompleteTransferCommand(transfer.transferId())));
        verify();
    }
    void verify() {
        pending(false); balances(963,137);
        if (command(CoreMessageType.TRANSFER_IN,recipient,7,TradingCommandCodec.encodeTransferFunds(transfer)).status()!=ResponseStatus.DUPLICATE
                || command(CoreMessageType.TRANSFER_OUT,sender,3,TradingCommandCodec.encodeTransferFunds(transfer)).status()!=ResponseStatus.DUPLICATE)
            throw new AssertionError("completed recovery lost funds identity");
        pending(false); balances(963,137);
        System.out.println("TRANSFER_GATE_PASS product="+line+" phase=completed source=963 target=137 total=1100 fundsDifference=0 retries=true");
    }
    public static void main(String[] args) {
        var line=ProductLine.requireExternalCode(System.getProperty("surprising.aeron.product-line"));
        try(var client=SurprisingAeronClient.connect(line,List.of("127.0.0.1"),"127.0.0.1",Duration.ofSeconds(10))) {
            var gate=new TransferGate(client);
            switch(System.getProperty("round68.transfer-mode")) {
                case "prepare" -> gate.prepare(); case "settle" -> gate.settle(); case "verify" -> gate.verify();
                default -> throw new IllegalArgumentException("mode");
            }
        }
    }
}

