 return {'path':str(path),'owner':owner,'major':major,'fields':fields,'methods':methods,'refs':refs,'classes':[pool[v[1]] for v in pool if isinstance(v,tuple) and v[0]==7],'target_type_strings':[s for s in pool if isinstance(s,str) and any(t in s for t in TARGETS)]}
