root=Path('/tmp/aeron-round68.fu8T6o');label=sys.argv[1];modules=sys.argv[2:];executed=set(re.findall(r'Running ([\w.$]+)',(root/(label+'-tests.log')).read_text()));out={'label':label,'modules':{},'cases':[]}
